00148 void WINAPI EventRecordCallback( PEVENT_RECORD record )
00149 {
00150 #ifdef TRACY_ON_DEMAND
00151     if( !GetProfiler().IsConnected() ) return;
00152 #endif
00153 
00154     const auto& hdr = record->EventHeader;
00155     switch( hdr.ProviderId.Data1 )
00156     {
00157     case 0x3d6fa8d1:    // Thread Guid
00158         if( hdr.EventDescriptor.Opcode == 36 )
00159         {
00160             const auto cswitch = (const CSwitch*)record->UserData;
00161 
00162             TracyLfqPrepare( QueueType::ContextSwitch );
00163             MemWrite( &item->contextSwitch.time, hdr.TimeStamp.QuadPart );
00164             MemWrite( &item->contextSwitch.oldThread, cswitch->oldThreadId );
00165             MemWrite( &item->contextSwitch.newThread, cswitch->newThreadId );
00166             MemWrite( &item->contextSwitch.cpu, record->BufferContext.ProcessorNumber );
00167             MemWrite( &item->contextSwitch.reason, cswitch->oldThreadWaitReason );
00168             MemWrite( &item->contextSwitch.state, cswitch->oldThreadState );
00169             TracyLfqCommit;
00170         }
00171         else if( hdr.EventDescriptor.Opcode == 50 )
00172         {
00173             const auto rt = (const ReadyThread*)record->UserData;
00174 
00175             TracyLfqPrepare( QueueType::ThreadWakeup );
00176             MemWrite( &item->threadWakeup.time, hdr.TimeStamp.QuadPart );
00177             MemWrite( &item->threadWakeup.thread, rt->threadId );
00178             TracyLfqCommit;
00179         }
00180         else if( hdr.EventDescriptor.Opcode == 1 || hdr.EventDescriptor.Opcode == 3 )
00181         {
00182             const auto tt = (const ThreadTrace*)record->UserData;
00183 
00184             uint64_t tid = tt->threadId;
00185             if( tid == 0 ) return;
00186             uint64_t pid = tt->processId;
00187             TracyLfqPrepare( QueueType::TidToPid );
00188             MemWrite( &item->tidToPid.tid, tid );
00189             MemWrite( &item->tidToPid.pid, pid );
00190             TracyLfqCommit;
00191         }
00192         break;
00193     case 0xdef2fe46:    // StackWalk Guid
00194         if( hdr.EventDescriptor.Opcode == 32 )
00195         {
00196             const auto sw = (const StackWalkEvent*)record->UserData;
00197             if( sw->stackProcess == s_pid )
00198             {
00199                 const uint64_t sz = ( record->UserDataLength - 16 ) / 8;
00200                 if( sz > 0 )
00201                 {
00202                     auto trace = (uint64_t*)tracy_malloc( ( 1 + sz ) * sizeof( uint64_t ) );
00203                     memcpy( trace, &sz, sizeof( uint64_t ) );
00204                     memcpy( trace+1, sw->stack, sizeof( uint64_t ) * sz );
00205                     TracyLfqPrepare( QueueType::CallstackSample );
00206                     MemWrite( &item->callstackSampleFat.time, sw->eventTimeStamp );
00207                     MemWrite( &item->callstackSampleFat.thread, sw->stackThread );
00208                     MemWrite( &item->callstackSampleFat.ptr, (uint64_t)trace );
00209                     TracyLfqCommit;
00210                 }
00211             }
00212         }
00213         break;
00214     default:
00215         break;
00216     }
00217 }
