00573                         while( ptr > buf2 && *ptr != '\\' ) ptr--;
00574                         if( *ptr == '\\' ) ptr++;
00575                         name = CopyStringFast( ptr );
00576                         return;
00577                     }
00578                 }
00579             }
00580         }
00581     }
00582 
00583     if( !threadSent )
00584     {
00585         threadName = CopyString( "???", 3 );
00586     }
00587     name = CopyStringFast( "???", 3 );
00588 }
00589 
00590 }
