00634 static bool CurrentProcOwnsThread( uint32_t tid )
00635 {
00636     const auto hash = tid & ( ThreadHashSize-1 );
00637     const auto hv = s_threadHash[hash];
00638     if( hv == tid ) return true;
00639     if( hv == -tid ) return false;
00640 
00641     char path[256];
00642     sprintf( path, "/proc/self/task/%d", tid );
00643     struct stat st;
00644     if( stat( path, &st ) == 0 )
00645     {
00646         s_threadHash[hash] = tid;
00647         return true;
00648     }
00649     else
00650     {
00651         s_threadHash[hash] = -tid;
00652         return false;
00653     }
00654 }
