00675 static void ProbePreciseIp( perf_event_attr& pe, unsigned long long config0, unsigned long long config1, pid_t pid )
00676 {
00677     pe.config = config1;
00678     pe.precise_ip = 3;
00679     while( pe.precise_ip != 0 )
00680     {
00681         const int fd = perf_event_open( &pe, pid, 0, -1, PERF_FLAG_FD_CLOEXEC );
00682         if( fd != -1 )
00683         {
00684             close( fd );
00685             break;
00686         }
00687         pe.precise_ip--;
00688     }
00689     pe.config = config0;
00690     while( pe.precise_ip != 0 )
00691     {
00692         const int fd = perf_event_open( &pe, pid, 0, -1, PERF_FLAG_FD_CLOEXEC );
00693         if( fd != -1 )
00694         {
00695             close( fd );
00696             break;
00697         }
00698         pe.precise_ip--;
00699     }
00700     TracyDebug( "  Probed precise_ip: %i\n", pe.precise_ip );
00701 }
