00708         const int fd = perf_event_open( &pe, pid, 0, -1, PERF_FLAG_FD_CLOEXEC );
00709         if( fd != -1 )
00710         {
00711             close( fd );
00712             break;
00713         }
00714         pe.precise_ip--;
00715     }
00716     TracyDebug( "  Probed precise_ip: %i\n", pe.precise_ip );
00717 }
