00719 static bool IsGenuineIntel()
00720 {
00721 #if defined __i386 || defined __x86_64__
00722     uint32_t regs[4] = {};
00723     __get_cpuid( 0, regs, regs+1, regs+2, regs+3 );
00724     char manufacturer[12];
00725     memcpy( manufacturer, regs+1, 4 );
00726     memcpy( manufacturer+4, regs+3, 4 );
00727     memcpy( manufacturer+8, regs+2, 4 );
00728     return memcmp( manufacturer, "GenuineIntel", 12 ) == 0;
00729 #else
00730     return false;
00731 #endif
00732 }
