00734 static const char* ReadFile( const char* path )
00735 {
00736     int fd = open( path, O_RDONLY );
00737     if( fd < 0 ) return nullptr;
00738 
00739     static char tmp[64];
00740     const auto cnt = read( fd, tmp, 63 );
00741     close( fd );
00742     if( cnt < 0 ) return nullptr;
00743     tmp[cnt] = '\0';
00744     return tmp;
00745 }
