00747 bool SysTraceStart( int64_t& samplingPeriod )
00748 {
00749 #ifndef CLOCK_MONOTONIC_RAW
00750     return false;
00751 #endif
00752 
00753     const auto paranoidLevelStr = ReadFile( "/proc/sys/kernel/perf_event_paranoid" );
00754     if( !paranoidLevelStr ) return false;
00755 #ifdef TRACY_VERBOSE
00756     int paranoidLevel = 2;
00757     paranoidLevel = atoi( paranoidLevelStr );
00758     TracyDebug( "perf_event_paranoid: %i\n", paranoidLevel );
00759 #endif
00760 
00761     int switchId = -1, wakeupId = -1, vsyncId = -1;
00762     const auto switchIdStr = ReadFile( "/sys/kernel/debug/tracing/events/sched/sched_switch/id" );
00763     if( switchIdStr ) switchId = atoi( switchIdStr );
00764     const auto wakeupIdStr = ReadFile( "/sys/kernel/debug/tracing/events/sched/sched_wakeup/id" );
00765     if( wakeupIdStr ) wakeupId = atoi( wakeupIdStr );
00766     const auto vsyncIdStr = ReadFile( "/sys/kernel/debug/tracing/events/drm/drm_vblank_event/id" );
00767     if( vsyncIdStr ) vsyncId = atoi( vsyncIdStr );
00768 
00769     TracyDebug( "sched_switch id: %i\n", switchId );
00770     TracyDebug( "sched_wakeup id: %i\n", wakeupId );
00771     TracyDebug( "drm_vblank_event id: %i\n", vsyncId );
00772 
00773 #ifdef TRACY_NO_SAMPLING
00774     const bool noSoftwareSampling = true;
00775 #else
00776     const char* noSoftwareSamplingEnv = GetEnvVar( "TRACY_NO_SAMPLING" );
00777     const bool noSoftwareSampling = noSoftwareSamplingEnv && noSoftwareSamplingEnv[0] == '1';
00778 #endif
00779 
00780 #ifdef TRACY_NO_SAMPLE_RETIREMENT
00781     const bool noRetirement = true;
00782 #else
00783     const char* noRetirementEnv = GetEnvVar( "TRACY_NO_SAMPLE_RETIREMENT" );
00784     const bool noRetirement = noRetirementEnv && noRetirementEnv[0] == '1';
00785 #endif
00786 
00787 #ifdef TRACY_NO_SAMPLE_CACHE
00788     const bool noCache = true;
00789 #else
00790     const char* noCacheEnv = GetEnvVar( "TRACY_NO_SAMPLE_CACHE" );
00791     const bool noCache = noCacheEnv && noCacheEnv[0] == '1';
00792 #endif
00793 
00794 #ifdef TRACY_NO_SAMPLE_BRANCH
00795     const bool noBranch = true;
00796 #else
00797     const char* noBranchEnv = GetEnvVar( "TRACY_NO_SAMPLE_BRANCH" );
00798     const bool noBranch = noBranchEnv && noBranchEnv[0] == '1';
00799 #endif
00800 
00801 #ifdef TRACY_NO_CONTEXT_SWITCH
00802     const bool noCtxSwitch = true;
00803 #else
00804     const char* noCtxSwitchEnv = GetEnvVar( "TRACY_NO_CONTEXT_SWITCH" );
00805     const bool noCtxSwitch = noCtxSwitchEnv && noCtxSwitchEnv[0] == '1';
00806 #endif
00807 
00808 #ifdef TRACY_NO_VSYNC_CAPTURE
00809     const bool noVsync = true;
00810 #else
00811     const char* noVsyncEnv = GetEnvVar( "TRACY_NO_VSYNC_CAPTURE" );
00812     const bool noVsync = noVsyncEnv && noVsyncEnv[0] == '1';
00813 #endif
00814 
00815     samplingPeriod = GetSamplingPeriod();
00816     uint32_t currentPid = (uint32_t)getpid();
00817 
00818     s_numCpus = (int)std::thread::hardware_concurrency();
00819 
00820     const auto maxNumBuffers = s_numCpus * (
00821         1 +     // software sampling
00822         2 +     // CPU cycles + instructions retired
00823         2 +     // cache reference + miss
00824         2 +     // branch retired + miss
00825         2 +     // context switches + wakeups
00826         1       // vsync
00827     );
00828     s_ring = (RingBuffer*)tracy_malloc( sizeof( RingBuffer ) * maxNumBuffers );
00829     s_numBuffers = 0;
00830 
00831     // software sampling
00832     perf_event_attr pe = {};
00833     pe.type = PERF_TYPE_SOFTWARE;
00834     pe.size = sizeof( perf_event_attr );
00835     pe.config = PERF_COUNT_SW_CPU_CLOCK;
00836     pe.sample_freq = GetSamplingFrequency();
00837     pe.sample_type = PERF_SAMPLE_TID | PERF_SAMPLE_TIME | PERF_SAMPLE_CALLCHAIN;
00838 #if LINUX_VERSION_CODE >= KERNEL_VERSION( 4, 8, 0 )
00839     pe.sample_max_stack = 127;
00840 #endif
00841     pe.disabled = 1;
00842     pe.freq = 1;
00843     pe.inherit = 1;
00844 #if !defined TRACY_HW_TIMER || !( defined __i386 || defined _M_IX86 || defined __x86_64__ || defined _M_X64 )
00845     pe.use_clockid = 1;
00846     pe.clockid = CLOCK_MONOTONIC_RAW;
00847 #endif
00848 
00849     if( !noSoftwareSampling )
00850     {
00851         TracyDebug( "Setup software sampling\n" );
00852         ProbePreciseIp( pe, currentPid );
00853         for( int i=0; i<s_numCpus; i++ )
00854         {
00855             int fd = perf_event_open( &pe, currentPid, i, -1, PERF_FLAG_FD_CLOEXEC );
00856             if( fd == -1 )
00857             {
00858                 pe.exclude_kernel = 1;
00859                 ProbePreciseIp( pe, currentPid );
00860                 fd = perf_event_open( &pe, currentPid, i, -1, PERF_FLAG_FD_CLOEXEC );
00861                 if( fd == -1 )
00862                 {
00863                     TracyDebug( "  Failed to setup!\n");
00864                     break;
00865                 }
00866                 TracyDebug( "  No access to kernel samples\n" );
00867             }
00868             new( s_ring+s_numBuffers ) RingBuffer( 64*1024, fd, EventCallstack );
00869             if( s_ring[s_numBuffers].IsValid() )
00870             {
00871                 s_numBuffers++;
00872                 TracyDebug( "  Core %i ok\n", i );
00873             }
00874         }
00875     }
00876 
00877     // CPU cycles + instructions retired
00878     pe = {};
00879     pe.type = PERF_TYPE_HARDWARE;
00880     pe.size = sizeof( perf_event_attr );
00881     pe.sample_freq = 5000;
00882     pe.sample_type = PERF_SAMPLE_IP | PERF_SAMPLE_TIME;
00883     pe.disabled = 1;
00884     pe.exclude_kernel = 1;
00885     pe.exclude_guest = 1;
00886     pe.exclude_hv = 1;
00887     pe.freq = 1;
00888     pe.inherit = 1;
00889 #if !defined TRACY_HW_TIMER || !( defined __i386 || defined _M_IX86 || defined __x86_64__ || defined _M_X64 )
00890     pe.use_clockid = 1;
00891     pe.clockid = CLOCK_MONOTONIC_RAW;
00892 #endif
00893 
00894     if( !noRetirement )
00895     {
00896         TracyDebug( "Setup sampling cycles + retirement\n" );
00897         ProbePreciseIp( pe, PERF_COUNT_HW_CPU_CYCLES, PERF_COUNT_HW_INSTRUCTIONS, currentPid );
00898         for( int i=0; i<s_numCpus; i++ )
00899         {
00900             const int fd = perf_event_open( &pe, currentPid, i, -1, PERF_FLAG_FD_CLOEXEC );
00901             if( fd != -1 )
00902             {
00903                 new( s_ring+s_numBuffers ) RingBuffer( 64*1024, fd, EventCpuCycles );
00904                 if( s_ring[s_numBuffers].IsValid() )
00905                 {
00906                     s_numBuffers++;
00907                     TracyDebug( "  Core %i ok\n", i );
00908                 }
00909             }
00910         }
00911 
00912         pe.config = PERF_COUNT_HW_INSTRUCTIONS;
00913         for( int i=0; i<s_numCpus; i++ )
00914         {
00915             const int fd = perf_event_open( &pe, currentPid, i, -1, PERF_FLAG_FD_CLOEXEC );
00916             if( fd != -1 )
00917             {
00918                 new( s_ring+s_numBuffers ) RingBuffer( 64*1024, fd, EventInstructionsRetired );
00919                 if( s_ring[s_numBuffers].IsValid() )
00920                 {
00921                     s_numBuffers++;
00922                     TracyDebug( "  Core %i ok\n", i );
00923                 }
00924             }
00925         }
00926     }
00927 
00928     // cache reference + miss
00929     if( !noCache )
00930     {
00931         TracyDebug( "Setup sampling CPU cache references + misses\n" );
00932         ProbePreciseIp( pe, PERF_COUNT_HW_CACHE_REFERENCES, PERF_COUNT_HW_CACHE_MISSES, currentPid );
00933         if( IsGenuineIntel() )
00934         {
00935             pe.precise_ip = 0;
00936             TracyDebug( "  CPU is GenuineIntel, forcing precise_ip down to 0\n" );
00937         }
00938         for( int i=0; i<s_numCpus; i++ )
00939         {
00940             const int fd = perf_event_open( &pe, currentPid, i, -1, PERF_FLAG_FD_CLOEXEC );
00941             if( fd != -1 )
00942             {
00943                 new( s_ring+s_numBuffers ) RingBuffer( 64*1024, fd, EventCacheReference );
00944                 if( s_ring[s_numBuffers].IsValid() )
00945                 {
00946                     s_numBuffers++;
00947                     TracyDebug( "  Core %i ok\n", i );
00948                 }
00949             }
00950         }
00951 
00952         pe.config = PERF_COUNT_HW_CACHE_MISSES;
00953         for( int i=0; i<s_numCpus; i++ )
00954         {
00955             const int fd = perf_event_open( &pe, currentPid, i, -1, PERF_FLAG_FD_CLOEXEC );
00956             if( fd != -1 )
00957             {
00958                 new( s_ring+s_numBuffers ) RingBuffer( 64*1024, fd, EventCacheMiss );
00959                 if( s_ring[s_numBuffers].IsValid() )
00960                 {
00961                     s_numBuffers++;
00962                     TracyDebug( "  Core %i ok\n", i );
00963                 }
00964             }
00965         }
00966     }
00967 
00968     // branch retired + miss
00969     if( !noBranch )
00970     {
00971         TracyDebug( "Setup sampling CPU branch retirements + misses\n" );
00972         ProbePreciseIp( pe, PERF_COUNT_HW_BRANCH_INSTRUCTIONS, PERF_COUNT_HW_BRANCH_MISSES, currentPid );
00973         for( int i=0; i<s_numCpus; i++ )
00974         {
00975             const int fd = perf_event_open( &pe, currentPid, i, -1, PERF_FLAG_FD_CLOEXEC );
00976             if( fd != -1 )
00977             {
00978                 new( s_ring+s_numBuffers ) RingBuffer( 64*1024, fd, EventBranchRetired );
00979                 if( s_ring[s_numBuffers].IsValid() )
00980                 {
00981                     s_numBuffers++;
00982                     TracyDebug( "  Core %i ok\n", i );
00983                 }
00984             }
00985         }
00986 
00987         pe.config = PERF_COUNT_HW_BRANCH_MISSES;
00988         for( int i=0; i<s_numCpus; i++ )
00989         {
00990             const int fd = perf_event_open( &pe, currentPid, i, -1, PERF_FLAG_FD_CLOEXEC );
00991             if( fd != -1 )
00992             {
00993                 new( s_ring+s_numBuffers ) RingBuffer( 64*1024, fd, EventBranchMiss );
00994                 if( s_ring[s_numBuffers].IsValid() )
00995                 {
00996                     s_numBuffers++;
00997                     TracyDebug( "  Core %i ok\n", i );
00998                 }
00999             }
01000         }
01001     }
01002 
01003     s_ctxBufferIdx = s_numBuffers;
01004 
01005     // vsync
01006     if( !noVsync && vsyncId != -1 )
01007     {
01008         pe = {};
01009         pe.type = PERF_TYPE_TRACEPOINT;
01010         pe.size = sizeof( perf_event_attr );
01011         pe.sample_period = 1;
01012         pe.sample_type = PERF_SAMPLE_TIME | PERF_SAMPLE_RAW;
01013         pe.disabled = 1;
01014         pe.config = vsyncId;
01015 #if !defined TRACY_HW_TIMER || !( defined __i386 || defined _M_IX86 || defined __x86_64__ || defined _M_X64 )
01016         pe.use_clockid = 1;
01017         pe.clockid = CLOCK_MONOTONIC_RAW;
01018 #endif
01019 
01020         TracyDebug( "Setup vsync capture\n" );
01021         for( int i=0; i<s_numCpus; i++ )
01022         {
01023             const int fd = perf_event_open( &pe, -1, i, -1, PERF_FLAG_FD_CLOEXEC );
01024             if( fd != -1 )
01025             {
01026                 new( s_ring+s_numBuffers ) RingBuffer( 64*1024, fd, EventVsync, i );
01027                 if( s_ring[s_numBuffers].IsValid() )
01028                 {
01029                     s_numBuffers++;
01030                     TracyDebug( "  Core %i ok\n", i );
01031                 }
01032             }
01033         }
01034     }
01035 
01036     // context switches
01037     if( !noCtxSwitch && switchId != -1 )
01038     {
01039         pe = {};
01040         pe.type = PERF_TYPE_TRACEPOINT;
01041         pe.size = sizeof( perf_event_attr );
01042         pe.sample_period = 1;
01043         pe.sample_type = PERF_SAMPLE_TIME | PERF_SAMPLE_RAW | PERF_SAMPLE_CALLCHAIN;
01044 #if LINUX_VERSION_CODE >= KERNEL_VERSION( 4, 8, 0 )
01045         pe.sample_max_stack = 127;
01046 #endif
01047         pe.disabled = 1;
01048         pe.inherit = 1;
01049         pe.config = switchId;
01050 #if !defined TRACY_HW_TIMER || !( defined __i386 || defined _M_IX86 || defined __x86_64__ || defined _M_X64 )
01051         pe.use_clockid = 1;
01052         pe.clockid = CLOCK_MONOTONIC_RAW;
01053 #endif
01054 
01055         TracyDebug( "Setup context switch capture\n" );
01056         for( int i=0; i<s_numCpus; i++ )
01057         {
01058             const int fd = perf_event_open( &pe, -1, i, -1, PERF_FLAG_FD_CLOEXEC );
01059             if( fd != -1 )
01060             {
01061                 new( s_ring+s_numBuffers ) RingBuffer( 256*1024, fd, EventContextSwitch, i );
01062                 if( s_ring[s_numBuffers].IsValid() )
01063                 {
01064                     s_numBuffers++;
01065                     TracyDebug( "  Core %i ok\n", i );
01066                 }
01067             }
01068         }
01069 
01070         if( wakeupId != -1 )
01071         {
01072             pe.config = wakeupId;
01073             pe.config &= ~PERF_SAMPLE_CALLCHAIN;
01074 
01075             TracyDebug( "Setup wakeup capture\n" );
01076             for( int i=0; i<s_numCpus; i++ )
01077             {
01078                 const int fd = perf_event_open( &pe, -1, i, -1, PERF_FLAG_FD_CLOEXEC );
01079                 if( fd != -1 )
01080                 {
01081                     new( s_ring+s_numBuffers ) RingBuffer( 64*1024, fd, EventWakeup, i );
01082                     if( s_ring[s_numBuffers].IsValid() )
01083                     {
01084                         s_numBuffers++;
01085                         TracyDebug( "  Core %i ok\n", i );
01086                     }
01087                 }
01088             }
01089         }
01090     }
01091 
01092     TracyDebug( "Ringbuffers in use: %i\n", s_numBuffers );
01093 
01094     traceActive.store( true, std::memory_order_relaxed );
01095     return true;
01096 }
