01103 static uint64_t* GetCallstackBlock( uint64_t cnt, RingBuffer& ring, uint64_t offset )
01104 {
01105     auto trace = (uint64_t*)tracy_malloc_fast( ( 1 + cnt ) * sizeof( uint64_t ) );
01106     ring.Read( trace+1, offset, sizeof( uint64_t ) * cnt );
01107 
01108 #if defined __x86_64__ || defined _M_X64
01109     // remove non-canonical pointers
01110     do
01111     {
01112         const auto test = (int64_t)trace[cnt];
01113         const auto m1 = test >> 63;
01114         const auto m2 = test >> 47;
01115         if( m1 == m2 ) break;
01116     }
01117     while( --cnt > 0 );
01118     for( uint64_t j=1; j<cnt; j++ )
01119     {
01120         const auto test = (int64_t)trace[j];
01121         const auto m1 = test >> 63;
01122         const auto m2 = test >> 47;
01123         if( m1 != m2 ) trace[j] = 0;
01124     }
01125 #endif
01126 
01127     for( uint64_t j=1; j<=cnt; j++ )
01128     {
01129         if( trace[j] >= (uint64_t)-4095 )       // PERF_CONTEXT_MAX
01130         {
01131             memmove( trace+j, trace+j+1, sizeof( uint64_t ) * ( cnt - j ) );
01132             cnt--;
01133         }
01134     }
01135 
01136     memcpy( trace, &cnt, sizeof( uint64_t ) );
01137     return trace;
01138 }
01139 
01140 void SysTraceWorker( void* ptr )
01141 {
01142     ThreadExitHandler threadExitHandler;
01143     SetThreadName( "Tracy Sampling" );
01144     InitRpmalloc();
01145     sched_param sp = { 99 };
01146     if( pthread_setschedparam( pthread_self(), SCHED_FIFO, &sp ) != 0 ) TracyDebug( "Failed to increase SysTraceWorker thread priority!\n" );
01147     auto ctxBufferIdx = s_ctxBufferIdx;
01148     auto ringArray = s_ring;
01149     auto numBuffers = s_numBuffers;
01150     for( int i=0; i<numBuffers; i++ ) ringArray[i].Enable();
01151     for(;;)
01152     {
01153 #ifdef TRACY_ON_DEMAND
01154         if( !GetProfiler().IsConnected() )
01155         {
01156             if( !traceActive.load( std::memory_order_relaxed ) ) break;
01157             for( int i=0; i<numBuffers; i++ )
01158             {
01159                 auto& ring = ringArray[i];
01160                 const auto head = ring.LoadHead();
01161                 const auto tail = ring.GetTail();
01162                 if( head != tail )
01163                 {
01164                     const auto end = head - tail;
01165                     ring.Advance( end );
01166                 }
01167             }
01168             if( !traceActive.load( std::memory_order_relaxed ) ) break;
01169             std::this_thread::sleep_for( std::chrono::milliseconds( 10 ) );
01170             continue;
01171         }
01172 #endif
01173 
01174         bool hadData = false;
01175         for( int i=0; i<ctxBufferIdx; i++ )
01176         {
01177             if( !traceActive.load( std::memory_order_relaxed ) ) break;
01178             auto& ring = ringArray[i];
01179             const auto head = ring.LoadHead();
01180             const auto tail = ring.GetTail();
01181             if( head == tail ) continue;
01182             assert( head > tail );
01183             hadData = true;
01184 
01185             const auto id = ring.GetId();
01186             assert( id != EventContextSwitch );
01187             const auto end = head - tail;
01188             uint64_t pos = 0;
01189             if( id == EventCallstack )
01190             {
01191                 while( pos < end )
01192                 {
01193                     perf_event_header hdr;
01194                     ring.Read( &hdr, pos, sizeof( perf_event_header ) );
01195                     if( hdr.type == PERF_RECORD_SAMPLE )
01196                     {
01197                         auto offset = pos + sizeof( perf_event_header );
01198 
01199                         // Layout:
01200                         //   u32 pid, tid
01201                         //   u64 time
01202                         //   u64 cnt
01203                         //   u64 ip[cnt]
01204 
01205                         uint32_t tid;
01206                         uint64_t t0;
01207                         uint64_t cnt;
01208 
01209                         offset += sizeof( uint32_t );
01210                         ring.Read( &tid, offset, sizeof( uint32_t ) );
01211                         offset += sizeof( uint32_t );
01212                         ring.Read( &t0, offset, sizeof( uint64_t ) );
01213                         offset += sizeof( uint64_t );
01214                         ring.Read( &cnt, offset, sizeof( uint64_t ) );
01215                         offset += sizeof( uint64_t );
01216 
01217                         if( cnt > 0 )
01218                         {
01219 #if defined TRACY_HW_TIMER && ( defined __i386 || defined _M_IX86 || defined __x86_64__ || defined _M_X64 )
01220                             t0 = ring.ConvertTimeToTsc( t0 );
01221 #endif
01222                             auto trace = GetCallstackBlock( cnt, ring, offset );
01223 
01224                             TracyLfqPrepare( QueueType::CallstackSample );
01225                             MemWrite( &item->callstackSampleFat.time, t0 );
01226                             MemWrite( &item->callstackSampleFat.thread, tid );
01227                             MemWrite( &item->callstackSampleFat.ptr, (uint64_t)trace );
01228                             TracyLfqCommit;
01229                         }
01230                     }
01231                     pos += hdr.size;
01232                 }
01233             }
01234             else
01235             {
01236                 while( pos < end )
01237                 {
01238                     perf_event_header hdr;
01239                     ring.Read( &hdr, pos, sizeof( perf_event_header ) );
01240                     if( hdr.type == PERF_RECORD_SAMPLE )
01241                     {
01242                         auto offset = pos + sizeof( perf_event_header );
01243 
01244                         // Layout:
01245                         //   u64 ip
01246                         //   u64 time
01247 
01248                         uint64_t ip, t0;
01249                         ring.Read( &ip, offset, sizeof( uint64_t ) );
01250                         offset += sizeof( uint64_t );
01251                         ring.Read( &t0, offset, sizeof( uint64_t ) );
01252 
01253 #if defined TRACY_HW_TIMER && ( defined __i386 || defined _M_IX86 || defined __x86_64__ || defined _M_X64 )
01254                         t0 = ring.ConvertTimeToTsc( t0 );
01255 #endif
01256                         QueueType type;
01257                         switch( id )
01258                         {
01259                         case EventCpuCycles:
01260                             type = QueueType::HwSampleCpuCycle;
01261                             break;
01262                         case EventInstructionsRetired:
01263                             type = QueueType::HwSampleInstructionRetired;
01264                             break;
01265                         case EventCacheReference:
01266                             type = QueueType::HwSampleCacheReference;
01267                             break;
01268                         case EventCacheMiss:
01269                             type = QueueType::HwSampleCacheMiss;
01270                             break;
01271                         case EventBranchRetired:
01272                             type = QueueType::HwSampleBranchRetired;
01273                             break;
01274                         case EventBranchMiss:
01275                             type = QueueType::HwSampleBranchMiss;
01276                             break;
01277                         default:
01278                             abort();
01279                         }
01280 
01281                         TracyLfqPrepare( type );
01282                         MemWrite( &item->hwSample.ip, ip );
01283                         MemWrite( &item->hwSample.time, t0 );
01284                         TracyLfqCommit;
01285                     }
01286                     pos += hdr.size;
01287                 }
01288             }
01289             assert( pos == end );
01290             ring.Advance( end );
01291         }
01292         if( !traceActive.load( std::memory_order_relaxed ) ) break;
01293 
01294         if( ctxBufferIdx != numBuffers )
01295         {
01296             const auto ctxBufNum = numBuffers - ctxBufferIdx;
01297 
01298             int activeNum = 0;
01299             uint16_t active[512];
01300             uint32_t end[512];
01301             uint32_t pos[512];
01302             for( int i=0; i<ctxBufNum; i++ )
01303             {
01304                 const auto rbIdx = ctxBufferIdx + i;
01305                 const auto rbHead = ringArray[rbIdx].LoadHead();
01306                 const auto rbTail = ringArray[rbIdx].GetTail();
01307                 const auto rbActive = rbHead != rbTail;
01308 
01309                 if( rbActive )
01310                 {
01311                     active[activeNum] = (uint16_t)i;
01312                     activeNum++;
01313                     end[i] = rbHead - rbTail;
01314                     pos[i] = 0;
01315                 }
01316                 else
01317                 {
01318                     end[i] = 0;
01319                 }
01320             }
01321             if( activeNum > 0 )
01322             {
01323                 hadData = true;
01324                 while( activeNum > 0 )
01325                 {
01326                     int sel = -1;
01327                     int selPos;
01328                     int64_t t0 = std::numeric_limits<int64_t>::max();
01329                     for( int i=0; i<activeNum; i++ )
01330                     {
01331                         auto idx = active[i];
01332                         auto rbPos = pos[idx];
01333                         assert( rbPos < end[idx] );
01334                         const auto rbIdx = ctxBufferIdx + idx;
01335                         perf_event_header hdr;
01336                         ringArray[rbIdx].Read( &hdr, rbPos, sizeof( perf_event_header ) );
01337                         if( hdr.type == PERF_RECORD_SAMPLE )
01338                         {
01339                             int64_t rbTime;
01340                             ringArray[rbIdx].Read( &rbTime, rbPos + sizeof( perf_event_header ), sizeof( int64_t ) );
01341                             if( rbTime < t0 )
01342                             {
01343                                 t0 = rbTime;
01344                                 sel = idx;
01345                                 selPos = i;
01346                             }
01347                         }
01348                         else
01349                         {
01350                             rbPos += hdr.size;
01351                             if( rbPos == end[idx] )
01352                             {
01353                                 memmove( active+i, active+i+1, sizeof(*active) * ( activeNum - i - 1 ) );
01354                                 activeNum--;
01355                                 i--;
01356                             }
01357                             else
01358                             {
01359                                 pos[idx] = rbPos;
01360                             }
01361                         }
01362                     }
01363                     if( sel >= 0 )
01364                     {
01365                         auto& ring = ringArray[ctxBufferIdx + sel];
01366                         auto rbPos = pos[sel];
01367                         auto offset = rbPos;
01368                         perf_event_header hdr;
01369                         ring.Read( &hdr, offset, sizeof( perf_event_header ) );
01370 
01371 #if defined TRACY_HW_TIMER && ( defined __i386 || defined _M_IX86 || defined __x86_64__ || defined _M_X64 )
01372                         t0 = ring.ConvertTimeToTsc( t0 );
01373 #endif
01374 
01375                         const auto rid = ring.GetId();
01376                         if( rid == EventContextSwitch )
01377                         {
01378                             // Layout:
01379                             //   u64 time
01380                             //   u64 cnt
01381                             //   u64 ip[cnt]
01382                             //   u32 size
01383                             //   u8  data[size]
01384                             // Data (not ABI stable, but has not changed since it was added, in 2009):
01385                             //   u8  hdr[8]
01386                             //   u8  prev_comm[16]
01387                             //   u32 prev_pid
01388                             //   u32 prev_prio
01389                             //   lng prev_state
01390                             //   u8  next_comm[16]
01391                             //   u32 next_pid
01392                             //   u32 next_prio
01393 
01394                             offset += sizeof( perf_event_header ) + sizeof( uint64_t );
01395 
01396                             uint64_t cnt;
01397                             ring.Read( &cnt, offset, sizeof( uint64_t ) );
01398                             offset += sizeof( uint64_t );
01399                             const auto traceOffset = offset;
01400                             offset += sizeof( uint64_t ) * cnt + sizeof( uint32_t ) + 8 + 16;
01401 
01402                             uint32_t prev_pid, next_pid;
01403                             long prev_state;
01404 
01405                             ring.Read( &prev_pid, offset, sizeof( uint32_t ) );
01406                             offset += sizeof( uint32_t ) + sizeof( uint32_t );
01407                             ring.Read( &prev_state, offset, sizeof( long ) );
01408                             offset += sizeof( long ) + 16;
01409                             ring.Read( &next_pid, offset, sizeof( uint32_t ) );
01410 
01411                             uint8_t reason = 100;
01412                             uint8_t state;
01413 
01414                             if(      prev_state & 0x0001 ) state = 104;
01415                             else if( prev_state & 0x0002 ) state = 101;
01416                             else if( prev_state & 0x0004 ) state = 105;
01417                             else if( prev_state & 0x0008 ) state = 106;
01418                             else if( prev_state & 0x0010 ) state = 108;
01419                             else if( prev_state & 0x0020 ) state = 109;
01420                             else if( prev_state & 0x0040 ) state = 110;
01421                             else if( prev_state & 0x0080 ) state = 102;
01422                             else                           state = 103;
01423 
01424                             TracyLfqPrepare( QueueType::ContextSwitch );
01425                             MemWrite( &item->contextSwitch.time, t0 );
01426                             MemWrite( &item->contextSwitch.oldThread, prev_pid );
01427                             MemWrite( &item->contextSwitch.newThread, next_pid );
01428                             MemWrite( &item->contextSwitch.cpu, uint8_t( ring.GetCpu() ) );
01429                             MemWrite( &item->contextSwitch.reason, reason );
01430                             MemWrite( &item->contextSwitch.state, state );
01431                             TracyLfqCommit;
01432 
01433                             if( cnt > 0 && prev_pid != 0 && CurrentProcOwnsThread( prev_pid ) )
01434                             {
01435                                 auto trace = GetCallstackBlock( cnt, ring, traceOffset );
01436 
01437                                 TracyLfqPrepare( QueueType::CallstackSampleContextSwitch );
01438                                 MemWrite( &item->callstackSampleFat.time, t0 );
01439                                 MemWrite( &item->callstackSampleFat.thread, prev_pid );
01440                                 MemWrite( &item->callstackSampleFat.ptr, (uint64_t)trace );
01441                                 TracyLfqCommit;
01442                             }
01443                         }
01444                         else if( rid == EventWakeup )
01445                         {
01446                             // Layout:
01447                             //   u64 time
01448                             //   u32 size
01449                             //   u8  data[size]
01450                             // Data:
01451                             //   u8  hdr[8]
01452                             //   u8  comm[16]
01453                             //   u32 pid
01454                             //   u32 prio
01455                             //   u64 target_cpu
01456 
01457                             offset += sizeof( perf_event_header ) + sizeof( uint64_t ) + sizeof( uint32_t ) + 8 + 16;
01458 
01459                             uint32_t pid;
01460                             ring.Read( &pid, offset, sizeof( uint32_t ) );
01461 
01462                             TracyLfqPrepare( QueueType::ThreadWakeup );
01463                             MemWrite( &item->threadWakeup.time, t0 );
01464                             MemWrite( &item->threadWakeup.thread, pid );
01465                             TracyLfqCommit;
01466                         }
01467                         else
01468                         {
01469                             assert( rid == EventVsync );
01470                             // Layout:
01471                             //   u64 time
01472                             //   u32 size
01473                             //   u8  data[size]
01474                             // Data (not ABI stable):
01475                             //   u8  hdr[8]
01476                             //   i32 crtc
01477                             //   u32 seq
01478                             //   i64 ktime
01479                             //   u8  high precision
01480 
01481                             offset += sizeof( perf_event_header ) + sizeof( uint64_t ) + sizeof( uint32_t ) + 8;
01482 
01483                             int32_t crtc;
01484                             ring.Read( &crtc, offset, sizeof( int32_t ) );
01485 
01486                             // Note: The timestamp value t0 might be off by a number of microseconds from the
01487                             // true hardware vblank event. The ktime value should be used instead, but it is
01488                             // measured in CLOCK_MONOTONIC time. Tracy only supports the timestamp counter
01489                             // register (TSC) or CLOCK_MONOTONIC_RAW clock.
01490 #if 0
01491                             offset += sizeof( uint32_t ) * 2;
01492                             int64_t ktime;
01493                             ring.Read( &ktime, offset, sizeof( int64_t ) );
01494 #endif
01495 
01496                             TracyLfqPrepare( QueueType::FrameVsync );
01497                             MemWrite( &item->frameVsync.id, crtc );
01498                             MemWrite( &item->frameVsync.time, t0 );
01499                             TracyLfqCommit;
01500                         }
01501 
01502                         rbPos += hdr.size;
01503                         if( rbPos == end[sel] )
01504                         {
01505                             memmove( active+selPos, active+selPos+1, sizeof(*active) * ( activeNum - selPos - 1 ) );
01506                             activeNum--;
01507                         }
01508                         else
01509                         {
01510                             pos[sel] = rbPos;
01511                         }
01512                     }
01513                 }
01514                 for( int i=0; i<ctxBufNum; i++ )
01515                 {
01516                     if( end[i] != 0 ) ringArray[ctxBufferIdx + i].Advance( end[i] );
01517                 }
01518             }
01519         }
01520         if( !traceActive.load( std::memory_order_relaxed ) ) break;
01521         if( !hadData )
01522         {
01523             std::this_thread::sleep_for( std::chrono::milliseconds( 1 ) );
01524         }
01525     }
01526 
01527     for( int i=0; i<numBuffers; i++ ) ringArray[i].~RingBuffer();
01528     tracy_free_fast( ringArray );
01529 }
01530 
01531 void SysTraceGetExternalName( uint64_t thread, const char*& threadName, const char*& name )
01532 {
01533     FILE* f;
01534     char fn[256];
01535     sprintf( fn, "/proc/%" PRIu64 "/comm", thread );
01536     f = fopen( fn, "rb" );
01537     if( f )
01538     {
01539         char buf[256];
01540         const auto sz = fread( buf, 1, 256, f );
01541         if( sz > 0 && buf[sz-1] == '\n' ) buf[sz-1] = '\0';
01542         threadName = CopyString( buf );
01543         fclose( f );
01544     }
01545     else
01546     {
01547         threadName = CopyString( "???", 3 );
01548     }
01549 
01550     sprintf( fn, "/proc/%" PRIu64 "/status", thread );
01551     f = fopen( fn, "rb" );
01552     if( f )
01553     {
01554         char* tmp = (char*)tracy_malloc_fast( 8*1024 );
01555         const auto fsz = (ptrdiff_t)fread( tmp, 1, 8*1024, f );
01556         fclose( f );
01557 
01558         int pid = -1;
01559         auto line = tmp;
01560         for(;;)
01561         {
01562             if( memcmp( "Tgid:\t", line, 6 ) == 0 )
01563             {
01564                 pid = atoi( line + 6 );
01565                 break;
01566             }
01567             while( line - tmp < fsz && *line != '\n' ) line++;
01568             if( *line != '\n' ) break;
01569             line++;
01570         }
01571         tracy_free_fast( tmp );
01572 
01573         if( pid >= 0 )
01574         {
01575             {
01576                 uint64_t _pid = pid;
01577                 TracyLfqPrepare( QueueType::TidToPid );
01578                 MemWrite( &item->tidToPid.tid, thread );
01579                 MemWrite( &item->tidToPid.pid, _pid );
01580                 TracyLfqCommit;
01581             }
01582             sprintf( fn, "/proc/%i/comm", pid );
01583             f = fopen( fn, "rb" );
01584             if( f )
01585             {
01586                 char buf[256];
01587                 const auto sz = fread( buf, 1, 256, f );
01588                 if( sz > 0 && buf[sz-1] == '\n' ) buf[sz-1] = '\0';
01589                 name = CopyStringFast( buf );
01590                 fclose( f );
01591                 return;
01592             }
01593         }
01594     }
01595     name = CopyStringFast( "???", 3 );
01596 }
